package com.alpharip.staffmod.IncidentPostMortemBoard; import com.google.gson.Gson;import com.google.gson.GsonBuilder;import java.io.*;import java.util.*;
public final class IncidentPostMortemStorage {
 private static final Gson GSON=new GsonBuilder().setPrettyPrinting().create();private IncidentPostMortemStorage(){} private static final class Snapshot {int version=1;List<IncidentRecord> incidents=new ArrayList<IncidentRecord>();}
 public static boolean save(File f,IncidentPostMortemBoard b){if(f==null||b==null)return false;File p=f.getParentFile();if(p!=null&&!p.exists()&&!p.mkdirs())return false;File tmp=new File(f.getAbsolutePath()+".tmp"),bak=new File(f.getAbsolutePath()+".bak");Writer w=null;try{Snapshot s=new Snapshot();s.incidents=b.getAll();w=new OutputStreamWriter(new FileOutputStream(tmp),"UTF-8");GSON.toJson(s,w);w.flush();w.close();w=null;if(bak.exists()&&!bak.delete())return false;boolean had=f.exists();if(had&&!f.renameTo(bak))return false;if(!tmp.renameTo(f)){if(had)bak.renameTo(f);tmp.delete();return false;}if(had)bak.delete();return true;}catch(Exception e){tmp.delete();return false;}finally{if(w!=null)try{w.close();}catch(Exception ignored){}}}
 public static boolean load(File f,IncidentPostMortemBoard b){if(f==null||b==null||!f.isFile())return false;Reader r=null;try{r=new InputStreamReader(new FileInputStream(f),"UTF-8");Snapshot s=GSON.fromJson(r,Snapshot.class);if(s==null||s.version!=1||s.incidents==null)return false;b.replaceAll(s.incidents);return true;}catch(Exception e){return false;}finally{if(r!=null)try{r.close();}catch(Exception ignored){}}}
}